const CHEMISTRY_CARD_BASE64 = '';
const PRF_CARD_BASE64 = '';
const ENDEMIAS_CARD_BASE64 = '';
const SEFIN_CARD_BASE64 = '';

module.exports = async function handler(req, res) {
  try {
    const productionHost = process.env.VERCEL_PROJECT_PRODUCTION_URL || 'sesau-certo.vercel.app';
    const sourceUrl = 'https://' + productionHost + '/index.html';

    const source = await fetch(sourceUrl, {
      headers: { 'user-agent': 'JR-Apostilas-Projeto1-Quimica/1.1' }
    });

    if (!source.ok) {
      res.statusCode = 502;
      res.setHeader('content-type', 'text/plain; charset=utf-8');
      res.end('Não foi possível carregar a plataforma original.');
      return;
    }

    let html = await source.text();
    html = html.replace('<head>', '<head><script>try{history.replaceState(null,\"\",\"/\")}catch(e){}</script>');
    if (!html.includes('jr-specific-card-style-v1')) {
      const cardCss = `
<style id="jr-specific-card-style-v1">
.jr-specific-card{position:relative!important;overflow:hidden!important;background:#09101d!important}
.jr-specific-visual{position:absolute;inset:0;z-index:0;background:radial-gradient(circle at 76% 17%,rgba(239,68,68,.30),transparent 29%),linear-gradient(145deg,#0b1420 0%,#090d14 52%,#29080b 100%)}
.jr-specific-visual:after{content:"";position:absolute;inset:0;background:linear-gradient(135deg,transparent 0 58%,rgba(248,113,113,.12) 58% 60%,transparent 60% 100%)}
.jr-specific-icon{position:absolute;right:18px;top:20px;font-size:54px;filter:drop-shadow(0 10px 18px rgba(0,0,0,.45));opacity:.96}
.jr-specific-lines{position:absolute;left:18px;right:18px;top:106px;height:78px;border-top:1px solid rgba(248,113,113,.22);border-bottom:1px solid rgba(248,113,113,.12);background:repeating-linear-gradient(180deg,transparent 0 17px,rgba(248,113,113,.07) 17px 18px)}
.jr-prf-card .jr-specific-visual{background:radial-gradient(circle at 76% 17%,rgba(59,130,246,.28),transparent 29%),linear-gradient(145deg,#071321,#101827 50%,#26070a)}
.jr-endemias-card .jr-specific-visual{background:radial-gradient(circle at 76% 17%,rgba(34,197,94,.18),transparent 29%),linear-gradient(145deg,#07161b,#0c1720 48%,#29070b)}
.jr-sefin-card .jr-specific-visual{background:radial-gradient(circle at 76% 17%,rgba(245,158,11,.18),transparent 29%),linear-gradient(145deg,#111827,#0a0e16 52%,#2b0908)}
.jr-specific-card .especifica-admin-shade{background:linear-gradient(180deg,rgba(2,6,23,.02) 20%,rgba(2,6,23,.28) 53%,rgba(2,6,23,.96) 100%)!important}
.jr-specific-card .especifica-admin-body p{-webkit-line-clamp:4!important}
.jr-specific-card:hover .jr-specific-visual{transform:none!important}
@media(max-width:700px){.jr-specific-icon{font-size:44px;right:13px;top:15px}.jr-specific-lines{left:13px;right:13px;top:88px;height:64px}.jr-specific-card .especifica-admin-body p{font-size:11px}}
</style>`;
      html = html.replace('</head>', cardCss + '</head>');
    }


    if (!html.includes('data-jr-card="quimica-seduc-pa"')) {
      const imageSrc = 'data:image/jpeg;base64,' + CHEMISTRY_CARD_BASE64;

      const card = `
<a class="especifica-card-link" data-jr-card="quimica-seduc-pa" href="https://especificas-premium.vercel.app/?area=quimica&v=12" target="_blank" rel="noopener">
  <div class="especifica-card">
    <img src="${imageSrc}" alt="SEDUC PA Professor de Química" width="640" height="960" loading="eager" decoding="async" style="width:100%;height:100%;object-fit:contain;object-position:center;display:block;background:#05070b;transform:none;transition:none">
  </div>
</a>
`;

      const sectionStart = html.indexOf('<section id="especificas"');
      if (sectionStart >= 0) {
        const sectionEnd = html.indexOf('</section>', sectionStart);
        if (sectionEnd >= 0) {
          const gridClose = html.lastIndexOf('</div>', sectionEnd);
          if (gridClose >= sectionStart) {
            html = html.slice(0, gridClose) + card + html.slice(gridClose);
          }
        }
      }
    }


    if (!html.includes('data-jr-card="prf-administrativo"')) {
      const prfCard = `
<a class="especifica-card-link" data-jr-card="prf-administrativo" href="https://especificas-premium.vercel.app/?area=prf&v=15" target="_blank" rel="noopener">
  <div class="especifica-card">
    <img src="data:image/jpeg;base64,${PRF_CARD_BASE64}" alt="PRF Agente Administrativo" width="640" height="960" loading="eager" decoding="async" style="width:100%;height:100%;object-fit:contain;object-position:center;display:block;background:#05070b;transform:none;transition:none">
  </div>
</a>
`;

      const prfSectionStart = html.indexOf('<section id="especificas"');
      if (prfSectionStart >= 0) {
        const prfSectionEnd = html.indexOf('</section>', prfSectionStart);
        if (prfSectionEnd >= 0) {
          const prfGridClose = html.lastIndexOf('</div>', prfSectionEnd);
          if (prfGridClose >= prfSectionStart) {
            html = html.slice(0, prfGridClose) + prfCard + html.slice(prfGridClose);
          }
        }
      }
    }

    if (!html.includes('data-jr-card="agente-endemias"')) {
      const endemiasCard = `
<a class="especifica-card-link" data-jr-card="agente-endemias" href="https://especificas-premium.vercel.app/?area=endemias&v=2" target="_blank" rel="noopener">
  <div class="especifica-card">
    <img src="data:image/jpeg;base64,${ENDEMIAS_CARD_BASE64}" alt="Agente de Combate às Endemias" width="640" height="960" loading="eager" decoding="async" style="width:100%;height:100%;object-fit:contain;object-position:center;display:block;background:#05070b;transform:none;transition:none">
  </div>
</a>
`;

      const sectionStart = html.indexOf('<section id="especificas"');
      if (sectionStart >= 0) {
        const sectionEnd = html.indexOf('</section>', sectionStart);
        if (sectionEnd >= 0) {
          const gridClose = html.lastIndexOf('</div>', sectionEnd);
          if (gridClose >= sectionStart) {
            html = html.slice(0, gridClose) + endemiasCard + html.slice(gridClose);
          }
        }
      }
    }

    if (!html.includes('data-jr-card="sefin-ro"')) {
      const sefinCard = `
<a class="especifica-card-link" data-jr-card="sefin-ro" href="https://especificas-premium.vercel.app/?area=sefin&v=2" target="_blank" rel="noopener">
  <div class="especifica-card">
    <img src="data:image/jpeg;base64,${SEFIN_CARD_BASE64}" alt="SEFIN/RO Material Geral" width="640" height="960" loading="eager" decoding="async" style="width:100%;height:100%;object-fit:contain;object-position:center;display:block;background:#05070b;transform:none;transition:none">
  </div>
</a>
`;

      const sectionStart = html.indexOf('<section id="especificas"');
      if (sectionStart >= 0) {
        const sectionEnd = html.indexOf('</section>', sectionStart);
        if (sectionEnd >= 0) {
          const gridClose = html.lastIndexOf('</div>', sectionEnd);
          if (gridClose >= sectionStart) {
            html = html.slice(0, gridClose) + sefinCard + html.slice(gridClose);
          }
        }
      }
    }

    res.statusCode = 200;
    res.setHeader('content-type', 'text/html; charset=utf-8');
    res.setHeader('cache-control', 'no-cache, no-store, must-revalidate');
    res.end(html);
  } catch (error) {
    res.statusCode = 500;
    res.setHeader('content-type', 'text/plain; charset=utf-8');
    res.end('Erro ao montar a página: ' + (error && error.message ? error.message : 'erro desconhecido'));
  }
};